	var query = event.payload.params.query;
	var arr = query.split("key=");
	var value = arr[1];
	var selectedFilterId = api.state.selectedCIFilter[0];
	var selectedClassFilter = api.state.ciFilters[selectedFilterId]['encodedQuery'];
	var finalQuery = "discovery_source=" + value;
	if(selectedClassFilter){
		finalQuery = finalQuery + "^" + selectedClassFilter;
	}

	return {
		route: 'list',
		fields: {
			table : "cmdb_multisource_data"
		},
